// The photographed textures the round-2 boards (2026-11-04, 風格設計稿_第二輪) need, baked as the boards use them:
// ambientCG Paper004 (CC0, https://ambientcg.com/view?id=Paper004), the file's kraft folder: grey, contrast 1.5, brightness
// 1.15, 600 px, JPEG q60, tiled at 1200 px and multiplied at 80 %; ambientCG Plaster001 (CC0), the stained glass's stone wall:
// 60 % grey, contrast 1.15, brightness 0.62, 700 px, JPEG q58, drawn as the wall itself. (The boards' Paper001 sheet bakes
// to white at every pixel under their own settings, so it changes nothing and is not kept.) Bake: out/research/boards-round2.
const KRAFT = 'data:image/jpeg;base64,';
const STONE = 'data:image/jpeg;base64,';

let kraft: ImageBitmap | undefined;
let stone: ImageBitmap | undefined;
const load = (src: string) => fetch(src).then((r) => r.blob()).then(createImageBitmap);
/** Resolves once both are decoded (a frame drawn before that goes without them). */
export const r2Textures: Promise<void> = typeof createImageBitmap === 'function' && typeof fetch === 'function'
  ? Promise.all([load(KRAFT), load(STONE)]).then(([k, s]) => { kraft = k; stone = s; }).catch(() => undefined)
  : Promise.resolve();

type Ctx = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D;
/** The kraft folder's fibre, multiplied over what is there at `a` (the board: 0.8). */
export function kraftOver(c: Ctx, a: number, x = 0, y = 0, w = 1920, h = 1080) {
  if (!kraft || a <= 0) return;
  c.save();
  c.globalCompositeOperation = 'multiply';
  c.globalAlpha = a;
  c.beginPath();
  c.rect(x, y, w, h);
  c.clip();
  for (let ty = y; ty < y + h; ty += 1200) for (let tx = x; tx < x + w; tx += 1200) c.drawImage(kraft, tx, ty, 1200, 1200);
  c.restore();
}
/** The stone wall round a window, laid as the picture itself; false before the texture is in. */
export function stoneWall(c: Ctx) {
  if (!stone) return false;
  for (let ty = 0; ty < 1080; ty += 1400) for (let tx = 0; tx < 1920; tx += 1400) c.drawImage(stone, tx, ty, 1400, 1400);
  return true;
}
